534	ssize_t vfs_read(struct file *file, char __user *buf, size_t count, loff_t *pos)
535	{
536		ssize_t ret;
537	
538		if (!(file->f_mode & FMODE_READ))
539			return -EBADF;
540		if (!(file->f_mode & FMODE_CAN_READ))
541			return -EINVAL;
542		if (unlikely(!access_ok(buf, count)))
543			return -EFAULT;
544	
545		ret = rw_verify_area(READ, file, pos, count);
546		if (ret)
547			return ret;
548		if (count > MAX_RW_COUNT)
549			count =  MAX_RW_COUNT;
550	
551		if (file->f_op->read)
552			ret = file->f_op->read(file, buf, count, pos);
553		else if (file->f_op->read_iter)
554			ret = new_sync_read(file, buf, count, pos);
555		else
556			ret = -EINVAL;
557		if (ret > 0) {
558			fsnotify_access(file);
559			add_rchar(current, ret);
560		}
561		inc_syscr(current);
562		return ret;
563	}
